import pytest
from mini_retriever.config import load_top_k

def test_default_top_k():
    assert load_top_k({}) == 3

def test_accepts_valid_override():
    assert load_top_k({"SEARCH_TOP_K": "4"}) == 4

@pytest.mark.parametrize("value", ["0", "21", "abc"])
def test_rejects_invalid_top_k(value):
    with pytest.raises(ValueError):
        load_top_k({"SEARCH_TOP_K": value})

